target.css:
:root {
  --cream: #f2ead8;
  --brown-dark: #3b2a1a;
  --brown-mid: #7a5230;
  --brown-light: #c4955a;
  --rust: #b04a1f;
  --olive: #5a6b3a;
  --ticket-border: #c4955a;
  --bg-ticket: #faf6ec;
  --text-muted: #8a6f4e;
  --dot-default: #c4955a;
  --dot-urgent: #b04a1f;
  --dot-done: #5a6b3a;
  --divider: #ddd0b0;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  margin: 0;
  padding: 20px;
  box-sizing: border-box;
}

.ticket {
  background-color: var(--bg-ticket);
  border: 2px solid var(--ticket-border);
  border-radius: 6px;
  width: 420px;
  padding: 0;
  overflow: hidden;
}

.ticket-header {
  background-color: var(--brown-dark);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 16px;
}

.ticket-label {
  color: var(--brown-light);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.ticket-number {
  color: var(--cream);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.ticket-body {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px 16px;
  padding: 16px;
}

.machine-info {
  grid-column: 1 / -1;
  border-bottom: 1px dashed var(--divider);
  padding-bottom: 10px;
}

.machine-name {
  margin: 0 0 2px 0;
  font-size: 18px;
  font-weight: 700;
  color: var(--brown-dark);
  line-height: 1.2;
}

.machine-year {
  margin: 0;
  font-size: 12px;
  color: var(--text-muted);
  font-weight: 500;
  letter-spacing: 0.05em;
}

.repair-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.repair-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--brown-mid);
  font-weight: 500;
  line-height: 1.3;
}

.repair-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background-color: var(--dot-default);
  flex-shrink: 0;
}

.repair-dot.urgent {
  background-color: var(--dot-urgent);
}

.repair-dot.done {
  background-color: var(--dot-done);
}

.cost-block {
  display: flex;
  flex-direction: column;
  gap: 6px;
  align-self: start;
}

.cost-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 13px;
  color: var(--brown-mid);
}

.cost-label {
  font-weight: 500;
}

.cost-value {
  font-weight: 600;
}

.total-row {
  border-top: 1px solid var(--divider);
  padding-top: 6px;
  margin-top: 2px;
}

.total-val {
  color: var(--rust);
  font-size: 15px;
  font-weight: 700;
}

.ticket-footer {
  background-color: var(--cream);
  border-top: 1px dashed var(--ticket-border);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 9px 16px;
}

.footer-name {
  font-size: 12px;
  font-weight: 700;
  color: var(--brown-dark);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.footer-date {
  font-size: 11px;
  color: var(--text-muted);
  font-weight: 500;
}

